    		SELECT SEQ_ACTIVITY_NO.NEXTVAL FROM DUAL

	INSERT 
	  INTO 
	       CL_ACTIVITY_BOARD 
	       (
	       ACTIVITY_NO
	     , ACTIVITY_TITLE
	     , ACTIVITY_CONTENT
	     , LAT
	     , LNG
	     , VIEW_COUNT
	     , STATUS
	     , ENROLL_DATE
	     , MEMBER_NO
	     , REGION_NO
	     , ADDRESS
           ) 
    VALUES 
    	   (
           #{activityNo}
         , #{title}
         , #{content}
         , #{lat}
         , #{lng}
         , DEFAULT
         , 'Y'
         , SYSDATE
         , #{memberNo}
         , #{regionNo}
         , #{address}
		   )

INSERT INTO CL_ACTIVITY_CERTIFICATION (
    ACTIVITY_BOARD_NO,
    CERTIFICATION_NO
) VALUES (
    #{activityNo},
    #{certificationNo}
)

